def classify(group):
    notes = []
    try:
        raise group
    except* ValueError as eg:
        notes.append(f"{len(eg.exceptions)} value problem(s)")
    except* (KeyError, IndexError) as eg:
        notes.append(f"{len(eg.exceptions)} lookup problem(s)")
    return notes

mixed = ExceptionGroup("mixed", [ValueError("a"), KeyError("k"), IndexError("i"), ValueError("b")])
print(classify(mixed))

try:
    classify(ExceptionGroup("odd", [ValueError("a"), OSError("disk")]))
except ExceptionGroup as leftover:
    print("propagated:", [type(e).__name__ for e in leftover.exceptions])
